import os
import importlib.util
import pytest

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
celsius_to_fahrenheit = target.celsius_to_fahrenheit


def test_freezing_point():
    assert celsius_to_fahrenheit(0) == 32.0


def test_boiling_point():
    assert celsius_to_fahrenheit(100) == 212.0


def test_minus_forty_equal():
    assert celsius_to_fahrenheit(-40) == -40.0


def test_body_temperature():
    assert celsius_to_fahrenheit(37) == 98.6


def test_room_temperature():
    assert celsius_to_fahrenheit(25) == 77.0


def test_one_degree():
    assert celsius_to_fahrenheit(1) == 33.8


def test_rounding_one_decimal():
    # 36.6 * 9/5 + 32 = 97.88 -> 97.9
    assert celsius_to_fahrenheit(36.6) == 97.9


def test_rounding_down():
    # 10.1 * 9/5 + 32 = 50.18 -> 50.2
    assert celsius_to_fahrenheit(10.1) == 50.2


def test_absolute_zero_rounded():
    # -273.15 * 9/5 + 32 = -459.67 -> -459.7
    assert celsius_to_fahrenheit(-273.15) == -459.7


def test_returns_float():
    assert isinstance(celsius_to_fahrenheit(20), float)


def test_float_input_accepted():
    assert celsius_to_fahrenheit(20.0) == 68.0


def test_negative_value():
    # -10 * 9/5 + 32 = 14.0
    assert celsius_to_fahrenheit(-10) == 14.0


def test_non_numeric_raises_type_error():
    with pytest.raises(TypeError):
        celsius_to_fahrenheit("20")


def test_none_raises_type_error():
    with pytest.raises(TypeError):
        celsius_to_fahrenheit(None)


def test_large_value():
    # 1000 * 9/5 + 32 = 1832.0
    assert celsius_to_fahrenheit(1000) == 1832.0

