import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
format_phone = target.format_phone


def test_basic_format():
    assert format_phone("4155552671") == "(415) 555-2671"


def test_another_format():
    assert format_phone("0123456789") == "(012) 345-6789"


def test_separators_rejected():
    for bad in ["415-555-2671", "(415) 555-2671", "415 555 2671"]:
        try:
            format_phone(bad)
            assert False, f"expected ValueError for {bad!r}"
        except ValueError:
            pass


def test_country_code_rejected():
    try:
        format_phone("14155552671")
        assert False, "expected ValueError"
    except ValueError:
        pass


def test_missing_digit_rejected():
    try:
        format_phone("415555267")
        assert False, "expected ValueError"
    except ValueError:
        pass


def test_non_string_rejected():
    try:
        format_phone(4155552671)
        assert False, "expected TypeError"
    except TypeError:
        pass


def test_plain_ascii_digits_only_superscript():
    # Spec: only plain digit strings are accepted.
    try:
        format_phone("415555267\u00b2")
        assert False, "expected ValueError for superscript digit"
    except ValueError:
        pass


def test_plain_ascii_digits_only_arabic_indic():
    # Spec: only plain digit strings are accepted.
    try:
        format_phone("\u0661\u0662\u0663\u0664\u0665\u0666\u0667\u0668\u0669\u0660")
        assert False, "expected ValueError for non-ASCII digits"
    except ValueError:
        pass

